"""DSec ordinary Host-file virtio-pmem/Guest-DAX comparison; prepare on A only.

Reuses completed v2 input artifacts. Creates a new private directory and prints
one bounded cap0 KVM root command. No SDK, Host DAX, kernel or service replacement.
"""
import argparse,base64,hashlib,json,os,re,socket,stat,sys,zlib
from pathlib import Path

ROOT=Path('/home/jwk/agent')
OLD=ROOT/'r/pm-a-v1/cache-compare-v2'
STAGE=ROOT/'r/dsec-host-pagecache-node-a-v1'


def need(value,reason):
    if not value:raise RuntimeError(reason)


def read(path,limit):
    need(path.is_absolute() and path.resolve(strict=True)==path and path.is_relative_to(ROOT),
         'Missing or redirected input')
    with path.open('rb') as stream:
        before=os.fstat(stream.fileno())
        need(stat.S_ISREG(before.st_mode) and before.st_uid==1204 and 0<before.st_size<=limit,
             'Unexpected input owner/type/size: '+str(path))
        data=stream.read(limit+1);after=os.fstat(stream.fileno())
    stamp=lambda s:(s.st_dev,s.st_ino,s.st_size,s.st_mtime_ns)
    need(stamp(before)==stamp(after) and len(data)==before.st_size,'Input changed')
    return data


def pin_file(row,expected):
    need(isinstance(row,dict) and set(row)<={'path','sha256','bytes'} and {'path','sha256'}<=set(row),
         'Unexpected input pin')
    path=Path(row['path'])
    need(path.resolve(strict=True)==path and path.is_relative_to(ROOT),'Redirected or outside experiment input')
    digest=hashlib.sha256()
    with path.open('rb') as stream:
        before=os.fstat(stream.fileno())
        need(stat.S_ISREG(before.st_mode) and before.st_uid==1204 and 0<before.st_size<=1024**3,
             'Unexpected artifact owner/type/size')
        for part in iter(lambda:stream.read(1024**2),b''):digest.update(part)
        after=os.fstat(stream.fileno())
    stamp=lambda s:(s.st_dev,s.st_ino,s.st_size,s.st_mtime_ns)
    need(stamp(before)==stamp(after)==stamp(path.stat()),'Artifact changed during hash')
    need(digest.hexdigest()==row['sha256']==expected['sha256'] and after.st_size==expected['bytes'],
         'Artifact differs from prior completed comparison: '+str(path))
    if 'bytes' in row:need(row['bytes']==after.st_size,'Declared length differs')


def validate_prior(previous,config):
    need(previous.get('status')=='ROOTFS_COMPONENT_COMPARISON_COMPLETED_NOT_GLOBAL_COW_PASS',
         'Prior v2 comparison was not completed; preserve inputs')
    need(previous.get('unresolvedFCPids')==[] and previous.get('wholeMatrixLeaseClosedAfterKnownFCExit') is True,
         'Prior experiment has unresolved children or lease')
    groups=previous.get('groups',[])
    need(len(groups)==4 and all(g.get('accepted') is True and g.get('allFCReapedAndLeasesClosed') is True for g in groups),
         'Expected four successful/released component groups')
    need({(g['mode'],g['N']) for g in groups}=={('block',1),('pmem',1),('block',2),('pmem',2)},'Prior matrix differs')
    need(config['guest']['providerSpec']['bytes']==64*1024**2 and config['lower']['bytes']==64*1024**2,
         'Expected retained 64MiB component image; do not substitute a business rootfs')
    need(re.fullmatch('[0-9a-f]{64}',config['expectedCommonSha256']) is not None,'Invalid test payload digest')
    need(config.get('comparisonUnit')=='jwk-rootfs-cache-compare-node-a-v2.service','Wrong retained configuration')
    return previous['sameInputs']


