def root_block(node,stage,files,environment):
    values={'HOST':'server1' if node=='node-a' else 'agent1','UNIT':'jwk-dsec-pagecache-'+node+'-v1.service',
        'STAGE':str(stage),'FILES':files,'EXTRA_ENV':environment}
    code='''import hashlib,os,socket,stat,subprocess
from pathlib import Path
assert os.geteuid()==0 and socket.gethostname()==HOST,'Use intended node root terminal'
assert subprocess.check_output(['/usr/bin/id','-u','jwk'],text=True).strip()=='1204'
assert subprocess.check_output(['/usr/bin/id','-g','jwk'],text=True).strip()=='1205'
assert subprocess.check_output(['/usr/bin/getent','group','kvm'],text=True).split(':')[2]=='36'
assert subprocess.check_output(['/usr/bin/systemctl','show',UNIT,'--property=LoadState','--value'],text=True).strip()=='not-found','Existing comparison unit preserved'
for name,pin in FILES.items():
 p=Path(name);assert p.resolve(strict=True)==p and p.is_relative_to(Path('/home/jwk/agent'))
 fd=os.open(p,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK);before=os.fstat(fd)
 assert stat.S_ISREG(before.st_mode) and before.st_uid==1204 and before.st_size<=131072
 with os.fdopen(fd,'rb') as f:raw=f.read(131073);after=os.fstat(f.fileno())
 assert len(raw)==before.st_size and (before.st_dev,before.st_ino,before.st_size,before.st_mtime_ns)==(after.st_dev,after.st_ino,after.st_size,after.st_mtime_ns)
 assert hashlib.sha256(raw).hexdigest()==pin,'Reviewed comparison code/config changed'
output=Path(STAGE)/'results';assert not output.exists() and not output.is_symlink()
assert Path('/dev/kvm').is_char_device()
command=['/usr/bin/systemd-run','--unit='+UNIT,'--collect','--wait','--pipe',
 '--property=Description=DSec Host file pagecache block versus Guest DAX comparison',
 '--property=User=jwk','--property=Group=jwk','--property=SupplementaryGroups=kvm',
 '--property=CapabilityBoundingSet=','--property=AmbientCapabilities=',
 '--property=NoNewPrivileges=yes','--property=PrivateNetwork=yes','--property=PrivateTmp=yes',
 '--property=Type=exec','--property=Restart=no','--property=KillMode=control-group',
 '--property=RuntimeMaxSec=600s','--property=TimeoutStopSec=20s','--property=LimitNOFILE=4096',
 '--property=MemoryMax=1536M','--property=UMask=0077']
for key,value in EXTRA_ENV.items():
 assert key=='GLIBC_TUNABLES' and value=='glibc.pthread.rseq=0'
 command.append('--property=Environment='+key+'='+value)
command+=['/usr/bin/python3','-I','-B',str(Path(STAGE)/'payload/entry.py'),'--config',str(Path(STAGE)/'compare.json'),'--output',str(output),'--run']
result=subprocess.run(command)
print('ROOTFS_COMPONENT_UNIT_EXIT='+str(result.returncode),flush=True)
raise SystemExit(result.returncode)
'''
    return "/usr/bin/python3 -I -B - <<'DSEC_HOST_PAGECACHE_REVIEWED_ROOT'\n"+''.join(k+'='+repr(v)+'\n' for k,v in values.items())+code+"DSEC_HOST_PAGECACHE_REVIEWED_ROOT\n"


def prepare():
    need(sys.platform=='linux' and os.uname().machine=='aarch64' and socket.gethostname()=='server1','Use A ARM64')
    need(os.getuid()==os.geteuid()==1204 and os.getgid()==os.getegid()==1205,'Use ordinary experiment user')
    need(not STAGE.exists() and not STAGE.is_symlink(),'Existing DSec run preserved; inspect its report')
    config=json.loads(read(OLD/'compare.json',32768))
    prior=json.loads(read(OLD/'results/return.json',2*1024**2))
    pins=validate_prior(prior,config)
    for name in ('firecracker','kernel','tools','upper'):
        pin_file(config['guest'][name],pins[name])
    if config['guest'].get('seccompFilter'):pin_file(config['guest']['seccompFilter'],pins['seccompFilter'])
    pin_file(config['lower'],pins['lower'])
    # Decode and validate every new source before creating the stage. No old
    # script is imported/executed, and no binary/image is downloaded or replaced.
    source={}
    for name,row in PAYLOAD.items():
        data=zlib.decompress(base64.b85decode(row['z85']))
        need(len(data)==row['bytes'] and hashlib.sha256(data).hexdigest()==row['sha256'],'Embedded source differs')
        source[name]=data
    os.umask(0o077)
    STAGE.mkdir(mode=0o700);(STAGE/'payload').mkdir(mode=0o700)
    files={}
    for name,data in source.items():
        path=STAGE/'payload'/name
        with path.open('xb') as stream:stream.write(data)
        files[str(path)]=hashlib.sha256(data).hexdigest()
    config['comparisonUnit']='jwk-dsec-pagecache-node-a-v1.service'
    # providerSpec is retained only as the original image identity/gate record.
    # The runtime does not connect its socket or acquire any UB object.
    raw=(json.dumps(config,indent=2)+'\n').encode()
    with (STAGE/'compare.json').open('xb') as stream:stream.write(raw)
    files[str(STAGE/'compare.json')]=hashlib.sha256(raw).hexdigest()
    command=root_block('node-a',STAGE,files,config.get('firecrackerEnvironment',{}))
    with (STAGE/'run-root.sh').open('x') as stream:stream.write(command)
    print(json.dumps({'status':'DSEC_HOST_PAGECACHE_PREPARED_NO_GUEST',
        'stage':str(STAGE),'SDK_called':False,'Guest_created':False,'servicesChanged':False,
        'HostFSDAXRequired':False,'matrix':['block1','pmem1','block2','pmem2'],
        'rootCommand':str(STAGE/'run-root.sh'),'report':str(STAGE/'results/return.json'),
        'scope':'ordinary Host pagecache reuse by Guest DAX; not cross-node memfile or original snapshot CoW'},indent=2),flush=True)
    print('BEGIN_DSEC_HOST_PAGECACHE_ROOT',flush=True)
    print(command,flush=True)
    print('END_DSEC_HOST_PAGECACHE_ROOT',flush=True)


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--run',action='store_true')
    args=parser.parse_args()
    if not args.run:
        print(json.dumps({'status':'PLAN_ONLY','Guest_created':False,'SDK_called':False,
                          'node':'node-a','maxSimultaneousGuests':2,'maxUnitSeconds':600}))
        return 0
    try:prepare()
    except Exception as error:
        print(json.dumps({'status':'STOPPED_DSEC_PREPARATION_NO_GUEST',
            'errorType':type(error).__name__,'reason':str(error),'SDK_called':False,
            'servicesChanged':False,'partialStagePreserved':str(STAGE)}),flush=True)
        return 1
    return 0


if __name__=='__main__':raise SystemExit(main())
